"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2501],{31733:e=>{e.exports=JSON.parse('{"functions":[{"name":"raycast","desc":"Performs a raycast against the physical world.\\n\\nThe ray is constructed using an origin and a direction, which is then scaled by the provided distance.\\nAn exclusion list can be provided to ignore specific instances during the raycast calculation.\\n\\n### Example Usage:\\n```lua\\nlocal result = physics.raycast(Vector3.new(0, 10, 0), Vector3.new(0, -1, 0), 100, { workspace.BasePlate })\\nif result then\\n    print(\\"Hit \\" .. result.instance.Name .. \\" at \\" .. tostring(result.position))\\nend\\n```","params":[{"name":"origin","desc":"The starting point of the ray.","lua_type":"vector"},{"name":"direction","desc":"The unit direction of the ray.","lua_type":"vector"},{"name":"distance","desc":"The maximum distance the ray should travel.","lua_type":"number"},{"name":"ignoreList","desc":"An array containing instances that the ray should ignore.","lua_type":"{Instance}"}],"returns":[{"desc":"A table containing hit information, or nil if no hit occurred.","lua_type":"RaycastResult?"}],"function_type":"static","errors":[{"lua_type":"\\"table must be an Array<RbxInstance>\\"","desc":"The ignoreList parameter is not a valid array of Instances."},{"lua_type":"\\"direction vector cannot be a zero vector\\"","desc":"The direction vector provided is a zero vector (Magnitude is 0)."},{"lua_type":"\\"distance cannot be less or equal to 0\\"","desc":"The distance provided is negative or zero."},{"lua_type":"\\"direction vector resulted in a zero vector\\"","desc":"The direction vector normalized and scaled by distance resulted in a zero vector."},{"lua_type":"\\"collection contained an object which was not an RbxInstance.\\"","desc":"The ignoreList contains an element that is not an Instance."},{"lua_type":"\\"raycast unavailable\\"","desc":"The physics engine is not currently available, likely due to physics updates being disabled."}],"source":{"line":36,"path":"src/libraries/physics.luau"}},{"name":"get_part_pool","desc":"Retrieves the internal \'pool\' index the part is assigned to within the RbxCli physics engine.\\n\\nThe pool determines the update rate of the part on the overlay\'s visuals and affects how \'fresh\' the data returned by other physics functions is.","params":[{"name":"part","desc":"The BasePart to query.","lua_type":"Instance"}],"returns":[{"desc":"The pool index the part is located in.","lua_type":"number"}],"function_type":"static","errors":[{"lua_type":"\\"object was freed\\"","desc":"The instance passed has been destroyed."},{"lua_type":"\\"variant cast failed\\"","desc":"The instance passed is not a BasePart."},{"lua_type":"\\"object is not tracked\\"","desc":"The part is not currently tracked by RbxCli."}],"source":{"line":61,"path":"src/libraries/physics.luau"}},{"name":"is_part_tracked","desc":"Checks if the specified BasePart is actively being updated by the RbxCli physics engine.\\n\\n### Behavior\\n*   Parts inside Characters are typically ignored and will return `false`.\\n*   Newly created parts (less than ~20 seconds old) may return `false` until they are picked up by the worker.\\n\\nA memory read may occur if physics updating is disabled to ensure the most accurate data is returned.","params":[{"name":"part","desc":"The BasePart to check.","lua_type":"Instance"}],"returns":[{"desc":"True if the part is actively being updated.","lua_type":"boolean"}],"function_type":"static","errors":[{"lua_type":"\\"object was freed\\"","desc":"The instance passed has been destroyed."},{"lua_type":"\\"variant cast failed\\"","desc":"The instance passed is not a BasePart."}],"source":{"line":80,"path":"src/libraries/physics.luau"}},{"name":"get_tracked_size","desc":"Retrieves the cached \'Size\' of the part from the last RbxCli update.\\n\\n### Performance Note\\nThis function reads from RbxCli\'s internal cache rather than reading directly from Roblox memory. \\n*   **Pros:** It is significantly faster than standard property access.\\n*   **Cons:** The data may be slightly out of date depending on the part\'s update pool.\\n\\nA memory read may occur if physics updating is disabled to ensure the most accurate data is returned.","params":[{"name":"part","desc":"The BasePart to query.","lua_type":"Instance"}],"returns":[{"desc":"The cached size of the part.","lua_type":"Vector3"}],"function_type":"static","errors":[{"lua_type":"\\"object was freed\\"","desc":"The instance passed has been destroyed."},{"lua_type":"\\"variant cast failed\\"","desc":"The instance passed is not a BasePart."},{"lua_type":"\\"object is not tracked\\"","desc":"The part is not currently in the physics engine."}],"source":{"line":101,"path":"src/libraries/physics.luau"}},{"name":"get_tracked_cframe","desc":"Retrieves the cached \'CFrame\' of the part from the last RbxCli update.\\n\\n### Performance Note\\nThis function reads from RbxCli\'s internal cache rather than reading directly from Roblox memory.\\n*   **Pros:** It is significantly faster than standard property access.\\n*   **Cons:** The data may be slightly out of date depending on the part\'s update pool.","params":[{"name":"part","desc":"The BasePart to query.","lua_type":"Instance"}],"returns":[{"desc":"The cached CFrame of the part.","lua_type":"CFrame"}],"function_type":"static","errors":[{"lua_type":"\\"object was freed\\"","desc":"The instance passed has been destroyed."},{"lua_type":"\\"variant cast failed\\"","desc":"The instance passed is not a BasePart."},{"lua_type":"\\"object is not tracked\\"","desc":"The part is not currently in the physics engine."}],"source":{"line":120,"path":"src/libraries/physics.luau"}},{"name":"can_part_be_tracked","desc":"Retrieves whether the given part is eligible to be tracked and updated by the physics engine.\\n\\nThis indicates if the part has been explicitly enabled or disabled for updates within RbxCli\'s PhysicsWorld (e.g., via configuration or internal logic).","params":[{"name":"part","desc":"The BasePart to check.","lua_type":"Instance"}],"returns":[{"desc":"True if the part is allowed to be tracked.","lua_type":"boolean"}],"function_type":"static","errors":[{"lua_type":"\\"object was freed\\"","desc":"The instance passed has been destroyed."},{"lua_type":"\\"variant cast failed\\"","desc":"The instance passed is not a BasePart."}],"source":{"line":135,"path":"src/libraries/physics.luau"}},{"name":"are_parts_updated","desc":"Checks if part data is being updated.\\n\\nIf this function returns false, it indicates that parts are not being updated. In this case, RbxCli will fall back to reading from raw memory instead of from its built-in cache. This may lead to reduced execution speed or for some APIs to completely fail.","params":[],"returns":[{"desc":"True if parts are being updated internally.","lua_type":"boolean"}],"function_type":"static","source":{"line":147,"path":"src/libraries/physics.luau"}},{"name":"is_point_in_part","desc":"Determines if a given point in world space is located within the bounds of a specified BasePart.","params":[{"name":"point","desc":"The world space point to check.","lua_type":"Vector3"},{"name":"part","desc":"The BasePart to test against.","lua_type":"Instance"}],"returns":[{"desc":"True if the point is inside the part, false otherwise.","lua_type":"boolean"}],"function_type":"static","errors":[{"lua_type":"\\"object was freed\\"","desc":"The instance passed has been destroyed."},{"lua_type":"\\"variant cast failed\\"","desc":"The instance passed is not a BasePart."},{"lua_type":"\\"failed to retrieve instance data.\\"","desc":"Memory read failure/ part data unavailable."}],"source":{"line":165,"path":"src/libraries/physics.luau"}},{"name":"is_point_in_box_volume","desc":"Determines if a given point in world space is located within the bounds of an box volume defined by a CFrame and size.","params":[{"name":"point","desc":"The world space point to check.","lua_type":"Vector3"},{"name":"boxCFrame","desc":"The CFrame representing the center and orientation of the box.","lua_type":"CFrame"},{"name":"boxSize","desc":"The size of the box along each axis.","lua_type":"Vector3"}],"returns":[{"desc":"True if the point is inside the box volume, false otherwise.","lua_type":"boolean"}],"function_type":"static","source":{"line":180,"path":"src/libraries/physics.luau"}},{"name":"is_point_in_sphere_volume","desc":"Determines if a given point in world space is located within the bounds of a sphere volume defined by a center point and radius.","params":[{"name":"point","desc":"The world space point to check.","lua_type":"Vector3"},{"name":"sphereCenter","desc":"The center of the sphere.","lua_type":"Vector3"},{"name":"sphereRadius","desc":"The radius of the sphere.","lua_type":"number"}],"returns":[{"desc":"True if the point is inside the sphere volume, false otherwise.","lua_type":"boolean"}],"function_type":"static","source":{"line":194,"path":"src/libraries/physics.luau"}}],"properties":[],"types":[{"name":"RaycastResult","desc":"","fields":[{"name":"distance","lua_type":"number","desc":"The distance from the origin to the hit position."},{"name":"hit_successful","lua_type":"boolean","desc":"Whether the raycast successfully hit a surface."},{"name":"position","lua_type":"vector","desc":"The world position where the ray hit."},{"name":"instance","lua_type":"Instance?","desc":"The Instance that was hit by the ray."}],"source":{"line":48,"path":"src/libraries/physics.luau"}}],"name":"physics","desc":"The physics library provides access to the world\'s physical state, allowing for spatial queries such as raycasting.","tags":["Library"],"source":{"line":6,"path":"src/libraries/physics.luau"}}')}}]);